  "usage_notes": [
    {
      "chord_quality": "dom7",
      "function_role": "harmonic-family-membership",
      "narrative": "Martino identifies the dominant 7th chord as the system's most flexible pivot point and structural target: 'The 7th chord having the all important tritone host the largest and most flexible of all the chord types. (7th b5, 7b9, 7th #5, 7th #9, 7th 9s, ren bg bs ect).' The dom7 is the convergence system's primary raw material because its embedded tritone makes it maximally convergent and generates the widest range of alteration options. Chapter 3, p. 8.",
      "source_principle_ids": [
        "pat-martino:system-of-tonal-convergence:convergence-system"
      ],
      "source_work_id": "system-of-tonal-convergence",
      "references": [
