          "source": "system-of-tonal-convergence",
          "citation": "Chapter 4 p.41"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "dom7b5",
      "function_role": "scale23-character-chord",
      "narrative": "Scale #23 prescribes a cluster of tritone-resolved dom7b5 voicings: 'Gb7b5, C7b5, C7b9, C7b9b5' are the convergence chords for Scale #23. Both C7b5 and Gb7b5 are present simultaneously, illustrating that the tritone-substitute and original dominant are co-equal approach options. Chapter 8, p. 62.",
      "source_principle_ids": [
        "pat-martino:system-of-tonal-convergence:convergence-system"
      ],
      "source_work_id": "system-of-tonal-convergence",
      "references": [
