          "citation": "Chapter 8 p.62"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "dom7b9",
      "function_role": "character-chord-from-scale",
      "narrative": "Martino's personal Scale #11 prescribes the dom7b9 sound as its defining character chord: 'My own personal scale containing an E-Bb tritone & the note Bb9 of which gives the scale a C7b9 sound.' The C7b9 is Scale #11's sonic identity and its convergence vehicle into F major. Chapter 5, p. 28.",
      "source_principle_ids": [
        "pat-martino:system-of-tonal-convergence:convergence-system"
      ],
      "source_work_id": "system-of-tonal-convergence",
      "references": [
