      "provenance": "extracted",
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "dom7b9",
      "function_role": "scale11-convergence-palette",
      "narrative": "Scale #11 prescribes a cluster of tritone-related chords including the dom7b9 as convergent approaches to FA79: 'C7b9, D7b5, Gb, Eb13' all converge on FA79 from Scale #11 (Chapter 7, p. 58). The C7b9 anchors the group; the other chords are interchangeable approach options sharing the same tritone resolution path.",
      "source_principle_ids": [
        "pat-martino:system-of-tonal-convergence:convergence-system"
      ],
      "source_work_id": "system-of-tonal-convergence",
      "references": [
