          "citation": "Chapter 10 p.80"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7#5",
      "function_role": "character-chord-from-scale",
      "narrative": "The augmented dominant C7+5 appears as a character chord in multiple scale contexts. Chapter 4 lists it as a product of the whole-tone scale alongside C7b5 (p. 41). Chapter 10 adds 'D7+5 also works beautifully as well as Bo7' as a convergent substitute for the Bb7-to-Eb progression (p. 80). The dom7#5 is thus a licensed augmented-dominant substitute alongside the tritone-substitute and diminished families.",
      "source_principle_ids": [
        "pat-martino:system-of-tonal-convergence:convergence-system"
      ],
      "source_work_id": "system-of-tonal-convergence",
      "references": [
