          "citation": "Chapter 4 p.41"
        },
        {
          "source": "system-of-tonal-convergence",
          "citation": "Chapter 10 p.80"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "dom7#5",
      "function_role": "scale24-convergence-target",
      "narrative": "Scale #24 prescribes C7+5 as one of its primary chord targets alongside the minor-major 7th and 13th: 'D-triangle7, C7+5, Gb13' are the tritone-related convergence chords for Scale #24, resolving to FA79 (Chapter 8, p. 62). The augmented dominant is Scale #24's characteristic dominant form.",
      "source_principle_ids": [
        "pat-martino:system-of-tonal-convergence:convergence-system"
      ],
      "source_work_id": "system-of-tonal-convergence",
      "references": [
