      "granularity_name": "other"
    },
    {
      "chord_quality": "min7",
      "function_role": "ii-chord-in-cadence",
      "narrative": "Martino identifies the II-V cadence as the convergence system's structural origin point: 'It was at this final juncture (II-V) where my convergence system was conceived.' The min7 (II chord) participates as the cadential setup, with example progressions G-7-C7-FA and I-VI-II-V-I cited as the practice vehicle for ear preparation. Chapter 3, p. 8; Chapter 4, p. 32.",
      "source_principle_ids": [
        "pat-martino:system-of-tonal-convergence:convergence-system"
      ],
      "source_work_id": "system-of-tonal-convergence",
      "references": [
