      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "min-maj7",
      "function_role": "scale24-convergence-target",
      "narrative": "Scale #24 prescribes D-triangle7 (minor-major 7th) as one of its primary convergence chord targets, appearing alongside C7+5 and Gb13, all resolving to FA79 (Chapter 8, p. 62). The min-maj7 is a co-equal approach chord form in Scale #24's harmonic palette, demonstrating that non-dominant chord types can participate directly in convergent motion.",
      "source_principle_ids": [
        "pat-martino:system-of-tonal-convergence:convergence-system"
      ],
      "source_work_id": "system-of-tonal-convergence",
      "references": [
