      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "min-maj7",
      "function_role": "color-tone-requirement-on-minor-target",
      "narrative": "When converging onto a minor chord using Scale #24 (which contains D-triangle7 as a character chord), Martino prescribes that scales containing major thirds must be applied to embellish the fifth of the minor chord rather than its root: 'Scale #3 has a major 3rd already in it so it has to be used as above to embellish the 5th of the F minor.' The min-maj7 character chord inherits this constraint when the resolution target is minor. Chapter 10, p. 84.",
      "source_principle_ids": [
        "pat-martino:system-of-tonal-convergence:convergence-system"
      ],
      "source_work_id": "system-of-tonal-convergence",
      "references": [
