      "provenance": "extracted",
      "granularity_level": "d",
      "granularity_name": "color-tone-policy"
    },
    {
      "chord_quality": "dim7",
      "function_role": "tritone-sharing-substitute",
      "narrative": "Martino prescribes the diminished seventh chord as a tritone-sharing substitute for the dominant V chord: 'Also the diminish chord D7 has the same tritone as the Bb7 (D-Ab). It smoothly voice leads into the Eb7.' The dim7 joins the tritone-substitute dominant as a licensed approach chord because it shares the critical tritone interval, not merely by convention. Chapter 10, p. 80.",
      "source_principle_ids": [
        "pat-martino:system-of-tonal-convergence:convergence-system"
      ],
      "source_work_id": "system-of-tonal-convergence",
      "references": [
