    },
    {
      "chord_quality": "dim7",
      "function_role": "dual-context-convergence",
      "narrative": "Martino prescribes the diminished scale as a convergence source for both the Fi7 (diminished/half-diminished) and FA7 (major) contexts simultaneously: 'DIMINISH Fi7 / FA7' (Chapter 8, p. 64). This dual applicability -- the dim7 chord serving both diminished-quality and major-quality resolution targets -- reflects the system's principle of symmetrical indifference, where diminished symmetry allows one chord to serve multiple tonal destinations.",
      "source_principle_ids": [
        "pat-martino:system-of-tonal-convergence:convergence-system"
      ],
      "source_work_id": "system-of-tonal-convergence",
      "references": [
