    },
    {
      "chord_quality": "dim7",
      "function_role": "symmetrical-indifference-multi-key",
      "narrative": "Martino prescribes exploiting the diminished scale's symmetrical indifference by starting on different internal notes to serve multiple tonal centers with the same scale form: 'same symmetrical indifference as the #4 scale which permits it to be used (starting on different notes) for converging cadences to several tonalities.' The dim7 chord derived from this scale inherits the same multi-key convergence utility. Chapter 4, p. 36.",
      "source_principle_ids": [
        "pat-martino:system-of-tonal-convergence:convergence-system"
      ],
      "source_work_id": "system-of-tonal-convergence",
      "references": [
